package org.gameflex.tv;
import android.app.*;import android.os.*;import android.webkit.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import android.content.Context;import android.util.Log;import org.json.JSONObject;import java.net.URI;import java.security.*;import java.io.*;import android.util.Base64;
/** Shared GameFlex console interface + the existing WebRTC player. No native command bridge. */
public final class MainActivity extends Activity {
 private WebView web;private URI origin;private android.widget.FrameLayout frame;private View fullscreen;private WebChromeClient.CustomViewCallback fullscreenCallback;
 private boolean settings=true,dialog=false,editing=false,leavingGame=false;private long lastMotion=0;private Handler handler=new Handler();
 private static final String DEFAULT_SERVER="http://192.168.1.63:2000";
 private final Runnable diagnostics=new Runnable(){public void run(){if(web!=null&&!settings&&playing()){web.evaluateJavascript("window.GameFlexTvStats?JSON.stringify(window.GameFlexTvStats()):'{}'",v->{if(v!=null&&v.length()<3000)Log.i("GameFlexTV","PLAYBACK "+v);});}handler.postDelayed(this,5000);}};
 @Override public void onCreate(Bundle b){super.onCreate(b);immersive();String saved=getPreferences(0).getString("server","");if(saved.isEmpty())serverSettings();else connect(saved);handler.postDelayed(diagnostics,5000);}
 private void immersive(){getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_STABLE);}
 private String asset(String name)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getAssets().open(name)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}return out.toString("UTF-8");}
 private String logo()throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getAssets().open("logo.png")){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP);}
 private static String hex(byte[] a){StringBuilder b=new StringBuilder();for(byte v:a)b.append(String.format("%02x",v&255));return b.toString();}
 private boolean playing(){return web!=null&&web.getUrl()!=null&&web.getUrl().contains("/streaming");}
 private void serverSettings(){exitFullscreen();settings=true;LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(65,42,65,30);root.setBackgroundColor(0xff0a1426);
  TextView title=new TextView(this);title.setText("GameFlex TV · NasPi");title.setTextColor(-1);title.setTextSize(30);root.addView(title);
  TextView info=new TextView(this);info.setText("Bibliothèque et émulateurs sur votre serveur. Image, son et commandes sur cette TV.");info.setTextColor(0xffb6c5dd);info.setTextSize(20);root.addView(info);
  EditText address=new EditText(this);address.setSingleLine(true);address.setTextColor(-1);address.setText(getPreferences(0).getString("server",DEFAULT_SERVER));address.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);root.addView(address);
  TextView message=new TextView(this);message.setTextColor(0xffffb2a5);root.addView(message);
  Button open=new Button(this);open.setText("Connecter GameFlex");root.addView(open);open.setOnClickListener(v->{try{String value=ServerPolicy.parse(address.getText().toString()).toString();getPreferences(0).edit().putString("server",value).apply();connect(value);}catch(Exception e){message.setText("Adresse refusée : utilisez NasPi sur le LAN ou https://gameflex.skino.app.");}});
  if(web!=null){Button resume=new Button(this);resume.setText("Revenir à GameFlex");root.addView(resume);resume.setOnClickListener(v->{settings=false;setContentView(frame);web.requestFocus();});}
  setContentView(root);open.requestFocus();}
 private void connect(String value){try{origin=ServerPolicy.parse(value);}catch(Exception e){serverSettings();return;}if(web!=null)web.destroy();web=new WebView(this);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(false);s.setUseWideViewPort(true);s.setLoadWithOverviewMode(false);
  web.setBackgroundColor(0xff08101e);WebView.setWebContentsDebuggingEnabled(false);web.setFocusable(true);web.setFocusableInTouchMode(true);
  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String u=r.getUrl().toString();if(r.isForMainFrame()&&u.equals("gameflex-tv://settings")){serverSettings();return true;}if(r.isForMainFrame()&&u.equals("gameflex-tv://home")){showShell();return true;}return r.isForMainFrame()&&!ServerPolicy.sameOrigin(origin,u);}
   @Override public void onPageFinished(WebView v,String url){if(ServerPolicy.sameOrigin(origin,url)){if(playing()){getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);try{v.evaluateJavascript(asset("stream-tv.js"),null);}catch(Exception ignored){}}else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}if(!playing())leavingGame=false;try{v.evaluateJavascript(asset("stream-tv.js"),null);v.evaluateJavascript(asset("tv-navigation.js"),null);}catch(Exception ignored){}v.requestFocus();}
   @Override public void doUpdateVisitedHistory(WebView v,String url,boolean reload){if(ServerPolicy.sameOrigin(origin,url)){if(playing())getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}}
   @Override public void onReceivedSslError(WebView v,SslErrorHandler h,android.net.http.SslError e){h.cancel();serviceError();}
   @Override public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError error){if(r.isForMainFrame())serviceError();}
  });
  web.setWebChromeClient(new WebChromeClient(){@Override public boolean onJsBeforeUnload(WebView v,String url,String message,JsResult result){if(leavingGame&&ServerPolicy.sameOrigin(origin,url)){result.confirm();return true;}return super.onJsBeforeUnload(v,url,message,result);}@Override public boolean onConsoleMessage(ConsoleMessage m){return true;}@Override public void onPermissionRequest(PermissionRequest r){r.deny();}@Override public void onShowCustomView(View v,CustomViewCallback cb){if(fullscreen!=null){cb.onCustomViewHidden();return;}fullscreen=v;fullscreenCallback=cb;web.setVisibility(View.GONE);frame.addView(v,new android.widget.FrameLayout.LayoutParams(-1,-1));v.requestFocus();}@Override public void onHideCustomView(){exitFullscreen();}});
  frame=new android.widget.FrameLayout(this);frame.addView(web,new android.widget.FrameLayout.LayoutParams(-1,-1));setContentView(frame);settings=false;showShell();}
 private void serviceError(){runOnUiThread(()->{LinearLayout root=new LinearLayout(this);root.setPadding(60,50,60,30);root.setOrientation(1);TextView title=new TextView(this);title.setText("GameFlex indisponible\nVérifiez NasPi et la connexion réseau.");title.setTextSize(26);root.addView(title);Button retry=new Button(this);retry.setText("Réessayer");root.addView(retry);retry.setOnClickListener(v->connect(origin.toString()));Button config=new Button(this);config.setText("Changer le serveur");root.addView(config);config.setOnClickListener(v->serverSettings());settings=true;setContentView(root);retry.requestFocus();});}
 private void showShell(){exitFullscreen();settings=false;getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);try{byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);String secret=hex(bytes),challenge=hex(MessageDigest.getInstance("SHA-256").digest(secret.getBytes("UTF-8"))),icon=logo();String html=asset("tv.html").replace("__LOGO__",icon).replace("__SERVER__",JSONObject.quote(origin.toString())).replace("__PAIR_SECRET__",JSONObject.quote(secret)).replace("__PAIR_CHALLENGE__",JSONObject.quote(challenge)).replace("__APP_SCRIPT__",asset("tv.js").replace("__LOGO__",icon));setContentView(frame);web.setVisibility(View.VISIBLE);web.loadDataWithBaseURL(origin.toString()+"/",html,"text/html","UTF-8",origin.toString()+"/");web.requestFocus();}catch(Exception e){serviceError();}}
 private void exitFullscreen(){if(fullscreen==null)return;frame.removeView(fullscreen);fullscreen=null;if(web!=null){web.setVisibility(View.VISIBLE);web.requestFocus();}if(fullscreenCallback!=null){fullscreenCallback.onCustomViewHidden();fullscreenCallback=null;}}
 private void leaveGame(){if(dialog)return;dialog=true;AlertDialog a=new AlertDialog.Builder(this).setTitle("Revenir à la bibliothèque ?").setMessage("Quitter cet écran de jeu. Vos réglages habituels de session et de sauvegarde sont conservés.").setPositiveButton("Revenir",(d,w)->{dialog=false;leavingGame=true;exitFullscreen();web.evaluateJavascript("window.GameFlexTv?GameFlexTv.returnToLibrary():location.assign('/')",null);}).setNeutralButton("Activer le son",(d,w)->{dialog=false;web.evaluateJavascript("(()=>{document.querySelectorAll('video,audio').forEach(v=>{v.muted=false;v.play().catch(()=>{});});})()",null);}).setNegativeButton("Continuer",(d,w)->dialog=false).create();a.setOnCancelListener(d->dialog=false);a.setOnShowListener(d->a.getButton(AlertDialog.BUTTON_NEGATIVE).requestFocus());a.show();}
 @Override public boolean dispatchKeyEvent(KeyEvent e){if(settings||dialog||web==null)return super.dispatchKeyEvent(e);int k=e.getKeyCode();if(editing){if(k==KeyEvent.KEYCODE_BACK&&e.getAction()==KeyEvent.ACTION_UP){editing=false;((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(web.getWindowToken(),0);return true;}return super.dispatchKeyEvent(e);}
  if(k==KeyEvent.KEYCODE_BACK||k==KeyEvent.KEYCODE_MENU){if(e.getAction()==KeyEvent.ACTION_UP){if(playing())leaveGame();else if(k==KeyEvent.KEYCODE_MENU)serverSettings();else web.evaluateJavascript("window.GameFlexTv&&GameFlexTv.back()",null);}return true;}
  if(playing()){
   int scan=TvKeycodes.scan(k);
   if(e.getScanCode()==0&&scan!=0){int key=k==23?66:k;KeyEvent normalized=new KeyEvent(e.getDownTime(),e.getEventTime(),e.getAction(),key,e.getRepeatCount(),e.getMetaState(),e.getDeviceId(),scan,e.getFlags(),InputDevice.SOURCE_KEYBOARD);return super.dispatchKeyEvent(normalized);}
   return super.dispatchKeyEvent(e);
  }
  String direction=k==19?"up":k==20?"down":k==21?"left":k==22?"right":null;
  if(direction!=null){if(e.getAction()==KeyEvent.ACTION_DOWN)web.evaluateJavascript("window.GameFlexTv&&GameFlexTv.move('"+direction+"')",null);return true;}
  if(k==23||k==66||k==KeyEvent.KEYCODE_BUTTON_A){if(e.getAction()==KeyEvent.ACTION_UP)web.evaluateJavascript("window.GameFlexTv&&GameFlexTv.ok()",r->{if("\"input\"".equals(r)){editing=true;((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(web,InputMethodManager.SHOW_IMPLICIT);}});return true;}
  if(k==KeyEvent.KEYCODE_BUTTON_B){if(e.getAction()==KeyEvent.ACTION_UP)web.evaluateJavascript("window.GameFlexTv&&GameFlexTv.back()",null);return true;}return super.dispatchKeyEvent(e);}
 @Override public boolean onGenericMotionEvent(MotionEvent e){if(!settings&&!dialog&&!playing()&&(e.getSource()&InputDevice.SOURCE_JOYSTICK)==InputDevice.SOURCE_JOYSTICK){float x=e.getAxisValue(MotionEvent.AXIS_HAT_X),y=e.getAxisValue(MotionEvent.AXIS_HAT_Y);if(Math.abs(x)<.5f)x=e.getAxisValue(MotionEvent.AXIS_X);if(Math.abs(y)<.5f)y=e.getAxisValue(MotionEvent.AXIS_Y);String dir=Math.abs(x)>.5f?(x>0?"right":"left"):Math.abs(y)>.5f?(y>0?"down":"up"):null;if(dir!=null&&System.currentTimeMillis()-lastMotion>220){lastMotion=System.currentTimeMillis();web.evaluateJavascript("window.GameFlexTv&&GameFlexTv.move('"+dir+"')",null);}return true;}return super.onGenericMotionEvent(e);}
 @Override public void onBackPressed(){if(playing())leaveGame();else if(!settings&&web!=null)web.evaluateJavascript("window.GameFlexTv&&GameFlexTv.back()",null);else super.onBackPressed();}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(web!=null)web.destroy();super.onDestroy();}
}
